const { execSync } = require('child_process');
const tasks = execSync('node /data/tools/fs/read_file.js /data/workspace/banle/TASKS.md').toString();
const arch1 = execSync('node /data/tools/fs/read_file.js /data/workspace/banle/docs/ARCHITECTURE_PORTAL.md').toString();
