const { execSync } = require('child_process');
const response = $node["AI: Coder Specialist"].json.response;
// Expecting AI to return JSON with filename and code
let data;
try {
  data = JSON.parse(response.replace(/```json|```/g, ''));
} catch (e) {
  throw new Error('AI failed to return valid JSON: ' + response);
}

const base64Code = Buffer.from(data.code).toString('base64');
execSync(`node /data/tools/fs/write_file.js /data/workspace/banle/${data.filename} "${base64Code}" overwrite`);

return { filename: data.filename, status: 'written' };

